Arity mismatches are the largest interface failure on set A: 41 TypeErrors (12.9% of answers) on top of 34 wrong names (10.7%). Let me see the arity messages and compare the final def line with the example test call, to classify (dropped a length parameter, dropped another argument, added an extra parameter, etc.).

```python
# Arity cases: compare final def signature with example call; classify dropped/added params.
def final_def_sig(code, name):
    try: tree = ast.parse(filter_code(code) or '')
    except Exception: return None
    for n in tree.body:
        if isinstance(n, ast.FunctionDef) and n.name == name:
            return [a.arg for a in n.args.args], len(n.args.defaults), n.args.vararg is not None
    return None
def example_call_args(qid):
    d = info[qid]; name = qmap[qid]['entry_point']
    for n in ast.walk(ast.parse(d['test'])):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == name:
            return [ast.get_source_segment(d['test'], a) for a in n.args]
ar = []
for r, m in res:
    if m.get('exc') == 'TypeError' and te_kind(m['msg']) == 'arity':
        name = qmap[r['id']]['entry_point']
        sig = final_def_sig(r['code'], name)
        ca = example_call_args(r['id'])
        refp = [a.arg for a in info[r['id']]['fd'].args.args]
        ar.append((r['id'], r['sample'], sig, len(ca), refp))
        print(r['id'], r['sample'], 'def', sig[0] if sig else None, '| call nargs', len(ca), '| ref', refp, '|', m['msg'][:70])
```

